"""WebSocket 连接管理 — 管理客户端连接与消息广播。"""

from __future__ import annotations

import asyncio
import json
from datetime import UTC, datetime
from typing import TYPE_CHECKING, Any

from autowsgr.infra.logger import get_logger


if TYPE_CHECKING:
    from fastapi import WebSocket


_log = get_logger('server.ws')

# 单条 WS 发送的硬上界。死连接不能拖住整轮广播（5.5）。
DEFAULT_SEND_TIMEOUT_SECONDS = 1.0


class WebSocketManager:
    """WebSocket 连接管理器。

    每个实例拥有独立的连接集合，``/ws/logs`` 与 ``/ws/task`` 不再串线（5.6）。
    广播时只在锁内取连接快照，锁外用 ``gather`` 并发发送；每条发送都有
    超时，超时或报错的连接会被立即剔除（5.5）。
    """

    def __init__(
        self,
        name: str = 'ws',
        send_timeout: float = DEFAULT_SEND_TIMEOUT_SECONDS,
    ) -> None:
        self._name = name
        self._send_timeout = send_timeout
        self._connections: set[WebSocket] = set()
        self._lock = asyncio.Lock()

    @property
    def name(self) -> str:
        """管理器名称，用于日志区分频道。"""
        return self._name

    @property
    def connection_count(self) -> int:
        """当前连接数（只读快照，供状态接口与测试使用）。"""
        return len(self._connections)

    def has_connections(self) -> bool:
        """是否有活跃连接。"""
        return bool(self._connections)

    async def connect(self, websocket: WebSocket) -> None:
        """接受新连接。"""
        await websocket.accept()
        async with self._lock:
            self._connections.add(websocket)
            count = len(self._connections)
        _log.info('[WS:{}] 新连接, 当前连接数: {}', self._name, count)

    async def disconnect(self, websocket: WebSocket) -> None:
        """断开连接（幂等）。"""
        async with self._lock:
            self._connections.discard(websocket)
            count = len(self._connections)
        _log.info('[WS:{}] 断开连接, 当前连接数: {}', self._name, count)

    async def broadcast(self, message: dict[str, Any]) -> None:
        """广播消息到所有连接。

        锁内只做快照，锁外并发发送。单条发送超过 ``send_timeout`` 或
        抛异常时，该连接会在本轮结束时被移出连接池。
        """
        async with self._lock:
            targets = list(self._connections)
        if not targets:
            return

        data = json.dumps(message, ensure_ascii=False)

        async def _send(websocket: WebSocket) -> tuple[WebSocket, Exception | None]:
            try:
                await asyncio.wait_for(
                    websocket.send_text(data),
                    timeout=self._send_timeout,
                )
            except Exception as exc:  # noqa: BLE001 - 单个连接失败不能影响广播
                return websocket, exc
            return websocket, None

        results = await asyncio.gather(
            *(_send(websocket) for websocket in targets),
            return_exceptions=True,
        )

        dead: list[tuple[WebSocket, Exception]] = []
        for result in results:
            if isinstance(result, BaseException):
                # gather 自身被取消时才会走到这里；没有可归属的连接。
                continue
            websocket, error = result
            if error is not None:
                dead.append((websocket, error))

        if not dead:
            return

        async with self._lock:
            for websocket, _error in dead:
                self._connections.discard(websocket)
            count = len(self._connections)
        _log.warning(
            '[WS:{}] 广播剔除 {} 个失效连接, 当前连接数: {}',
            self._name,
            len(dead),
            count,
        )

    async def send_log(
        self,
        level: str,
        message: str,
        channel: str = '',
        *,
        timestamp: str | None = None,
        source: str | None = None,
    ) -> None:
        """发送日志消息（/ws/logs 的唯一生产者入口）。"""
        payload: dict[str, Any] = {
            'type': 'log',
            'timestamp': timestamp or datetime.now(UTC).isoformat(),
            'level': level,
            'channel': channel,
            'message': message,
        }
        if source:
            payload['source'] = source
        await self.broadcast(payload)

    async def send_task_update(
        self,
        task_id: str,
        status: str,
        progress: dict[str, Any] | None = None,
        result: dict[str, Any] | None = None,
    ) -> None:
        """发送任务状态更新。"""
        payload: dict[str, Any] = {
            'type': 'task_update',
            'task_id': task_id,
            'status': status,
        }
        if progress:
            payload['progress'] = progress
        if result:
            payload['result'] = result
        await self.broadcast(payload)

    async def send_ui_state_update(
        self,
        *,
        page: str | None,
        stack: list[str] | tuple[str, ...] | None,
        phase: str | None,
        substate: str | None = None,
    ) -> None:
        """发送 UI 状态快照（4.5）。

        负载固定为 ``type/page/stack/phase/substate``：前端据此显示当前
        页面、导航路径与战斗阶段。``page=None`` 表示任务刚开始、尚未识别。
        """
        await self.broadcast(
            {
                'type': 'ui_state_update',
                'page': page,
                'stack': list(stack or ()),
                'phase': phase,
                'substate': substate,
            }
        )

    async def send_loot_update(self, loot_count: int, ship_count: int) -> None:
        """发送结构化掉落事件（5.9）。

        事件字段固定为 ``type/loot_count/ship_count``；前端以它作为停止
        条件的主数据源，日志解析只作为 WS 不可用时的兜底。
        """
        await self.broadcast(
            {
                'type': 'loot_update',
                'loot_count': int(loot_count),
                'ship_count': int(ship_count),
            }
        )

    async def send_task_completed(
        self,
        task_id: str,
        success: bool,
        result: dict[str, Any] | None = None,
        error: str | None = None,
    ) -> None:
        """发送任务完成通知。"""
        await self.broadcast(
            {
                'type': 'task_completed',
                'task_id': task_id,
                'success': success,
                'result': result,
                'error': error,
            }
        )


# 5.6：按频道拆分连接池，避免 /ws/logs 与 /ws/task 串线。
task_ws_manager = WebSocketManager('task')
log_ws_manager = WebSocketManager('logs')

# 向后兼容：旧代码（以及可能的外部导入）默认指向任务频道。
ws_manager = task_ws_manager
